{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tazemetostat, which shares the amidoxime and morpholinomethyl-substituted heteroaromatic framework, has a median absolute oral bioavailability of 31.8% (range 20.2-49.8%) in patients, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Entrectinib, a heteroaromatic drug containing a morpholine and pyrazole/benzimidazole-like core, has >50% oral bioavailability in humans, supporting high oral absorption for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "R406, a benzimidazole-containing drug, has 55% absolute oral bioavailability in humans, showing that this heteroaromatic class can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Mebendazole, a benzimidazole carbamate, has only about 1% human bioavailability, providing a low-F counterexample; however, it lacks the query's amidoxime and morpholine solubilizing groups.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Revefenacin has <3% oral bioavailability in humans, but it is an inhaled muscarinic antagonist with intentionally low oral absorption and low structural transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "MR309, despite containing a morpholine and pyrazole, had poor oral bioavailability in humans, a contradictory example, though its lipophilic naphthalene and lack of amidoxime reduce transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's amidoxime and morpholinomethyl benzimidazole/pyrazole scaffold aligns most closely with tazemetostat, whose absolute oral bioavailability is ~32-34% in humans, and with other orally bioavailable heteroaromatic drugs (entrectinib >50%, R406 55%). Low-F analogues are either benzimidazole carbamates with poor solubility or inhaled/first-pass-limited drugs lacking the query's solubilizing morpholine and amidoxime; thus high F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental PK data for the query molecule.",
    "All retrieved evidence molecules have low Morgan similarity (<0.28), limiting direct transferability.",
    "No solubility, permeability, or metabolic stability data are available for the query.",
    "Human absolute bioavailability of the exact query has not been measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

